+fn insert_partial(
+    registry: &mut BTreeMap<String, PartialDef>,
+    name: String,
+    def: PartialDef,
+) -> Result<(), String> {
+    if registry.contains_key(&name) {
+        return Err(format!(
+            "duplicate partial '{name}' — defined more than once (an in-source `{{{{#inline}}}}` and a `partials = […]` file, or twice in the map)"
